import{_ as o,o as a,c,a3 as r}from"./chunks/framework.CWSmAuPU.js";const p=JSON.parse('{"title":"0030 接单器：共享机器上定时接卡片、转达回复","description":"","frontmatter":{"editLink":false},"headers":[],"relativePath":"reference/adr/0030-card-intake-process.md","filePath":"reference/adr/0030-card-intake-process.md","lastUpdated":null}'),t={name:"reference/adr/0030-card-intake-process.md"};function d(s,e,i,l,n,u){return a(),c("div",null,[...e[0]||(e[0]=[r('<div><h1 id="_0030-接单器-共享机器上定时接卡片、转达回复" tabindex="-1">0030 接单器：共享机器上定时接卡片、转达回复 <a class="header-anchor" href="#_0030-接单器-共享机器上定时接卡片、转达回复" aria-label="Permalink to &quot;0030 接单器：共享机器上定时接卡片、转达回复&quot;">​</a></h1><ul><li>状态：已采纳（1.11.0-beta.1；建在 <a href="./0029-requirements-from-cards">0029</a> 之上）</li></ul><h2 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to &quot;背景&quot;">​</a></h2><p>1.10 已经可以从一张卡片开始需求（<code>req start --from</code>）、把需求方在卡片中的回复转给需求会话（<code>req card check</code>），但这两步都要有人运行。&quot;软件工厂&quot;要求需求方只在卡片上操作：写好卡片、标题加上约定的标识，就有一台共享研发机器接手。</p><h2 id="决定" tabindex="-1">决定 <a class="header-anchor" href="#决定" aria-label="Permalink to &quot;决定&quot;">​</a></h2><ul><li><strong>一个常驻进程，两件事</strong>：<code>req factory run</code> 每隔 <code>factory.pollMinutes</code>（默认 5 分钟）检查一次：先用对接配置的 <code>list</code> 命令列出各空间（本机登记仓库的 <code>cardSource.projectId</code>）中的卡片，标题以 <code>factory.titleTags</code>（默认 <code>[AI]</code>、<code>【AI】</code>）开头、本机还没开始过的，按 1.10 的 <code>req start --from</code> 开始（按子系统选仓库、建需求会话）；再按 <code>req card check --all</code> 转达回复，跳过流水线已完成的需求。同一台机器上一次只做一次检查（<code>~/.req-kit/factory/poll.lock</code>）。</li><li><strong>轮询外部系统，不用回调</strong>：需求管理系统没有我们能用的事件推送；轮询的间隔是几分钟，对需求开发足够，失败了下次再来。卡片状态、条件（例如只查&quot;新建&quot;的用户故事）写在 <code>list</code> 的参数里，由团队配置决定。</li><li><strong>克制地接单</strong>：每次最多开始 <code>factory.maxNewPerPoll</code>（默认 3）个需求，其余下次再接；流水线本身仍受 <code>maxConcurrentPipelines</code> 限制。接不了的卡片（例如子系统没有对应的仓库）记下原因，卡片的标题和子系统不变就一天内不再试，<code>req factory status</code> 中可以看到。</li><li><strong>只读卡片、不改卡片状态来&quot;占位&quot;</strong>：本机的登记（<code>~/.req-kit/cards/</code>）就是去重的依据。卡片状态仍只由流水线事件改（开发中、待测试）。将来多台机器同时接单时再引入占位（例如改状态或经内网 Hub 派工），见 <a href="./0029-requirements-from-cards">0029</a>。</li><li><strong>运行方式交给系统</strong>：<code>req factory start</code> / <code>stop</code> 在后台运行，适合先试；长期运行用系统服务（<code>req factory service</code> 给出 systemd 用户服务或 Windows 计划任务的写法），机器重启后自动恢复。接单器通过 Paseo daemon 创建需求会话，daemon 需要同时运行。</li><li><strong>配置只在本机或团队配置中</strong>：<code>factory</code> 和 <code>integrations</code> 一样会让机器做事，写在项目配置中会被忽略。</li></ul><h2 id="影响" tabindex="-1">影响 <a class="header-anchor" href="#影响" aria-label="Permalink to &quot;影响&quot;">​</a></h2><ul><li>对接配置新增 <code>list</code>（参数可用 <code>{projectId}</code>、<code>{page}</code>、<code>{pageSize}</code>、<code>{titleTag}</code>；<code>fields</code> 写每张卡片中 id、title 等的位置；<code>items</code> 写输出中列表的位置，不写时依次找 data.list、data.records、data.items、data.rows、data）。</li><li>新增配置 <code>factory</code>（<code>pollMinutes</code>、<code>titleTags</code>、<code>maxNewPerPoll</code>）、命令 <code>req factory once | run | start | stop | status | service</code>、本机目录 <code>~/.req-kit/factory/</code>（日志、状态、没能接的卡片）。</li><li><code>req start --from</code> 中途失败（例如 Paseo 没在运行，会话没建成）时，再次运行会补建会话，而不是当作已经开始过。</li></ul></div><p class="source-note">本页由仓库中的 <a href="https://github.com/yiyisf/paseo-req-kit/blob/main/docs/adr/0030-card-intake-process.md">docs/adr/0030-card-intake-process.md</a> 生成。<a href="https://github.com/yiyisf/paseo-req-kit/edit/main/docs/adr/0030-card-intake-process.md">在 GitHub 上编辑</a></p>',2)])])}const m=o(t,[["render",d]]);export{p as __pageData,m as default};
